// Referências de credenciais são selecionadas nos HTTPs. Corte e enabled são a única liberação deste fluxo.
const cfg={
  "enabled": false,
  "serviceUrl": "https://PROJECT_REF.supabase.co/functions/v1/exam-document-service",
  "mailbox": "exames@example.invalid",
  "driveFolderId": "SELECT_PRIVATE_DRIVE_FOLDER",
  "intakeCutoff": "",
  "notificationCutoff": "",
  "manualMessageId": "",
  "dedicatedMailbox": false,
  "allowedSenders": [],
  "examSubjectHints": [
    "exame",
    "laudo",
