    "resultado de exame",
    "hemograma",
    "ultrassom"
  ],
  "maxBytes": 20971520,
  "maxMimeDepth": 8,
  "maxPages": 100,
  "includeSpamTrash": false,
  "worker": "n8n-exames-operacional",
  "chatwootBaseUrl": "https://chatwoot.example.invalid",
